package com.integrydt.backend.controller;
import com.integrydt.backend.security.AuthenticatedUser;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/catalog") @PreAuthorize("hasAuthority('PERM_tools.read')") public class CatalogController{private final JdbcTemplate db;public CatalogController(JdbcTemplate d){db=d;}@GetMapping("/tools")public Object tools(Authentication a){String c=((AuthenticatedUser)a.getPrincipal()).companyId();return db.queryForList("SELECT t.code toolCode,t.name toolName,g.code gadgetCode,g.name gadgetName,g.risk_level riskLevel,gv.version,gv.status FROM company_tools ct JOIN tools t ON t.id=ct.tool_id AND t.enabled=1 JOIN gadgets g ON g.id=t.gadget_id AND g.enabled=1 JOIN company_gadget_policies cgp ON cgp.company_id=ct.company_id AND cgp.gadget_id=g.id AND cgp.enabled=1 JOIN gadget_versions gv ON gv.gadget_id=g.id AND gv.status='published' WHERE ct.company_id=? AND ct.enabled=1 AND gv.id=(SELECT gv2.id FROM gadget_versions gv2 WHERE gv2.gadget_id=g.id AND gv2.status='published' ORDER BY gv2.published_at DESC,gv2.created_at DESC LIMIT 1) ORDER BY t.name",c);}}
